export const TYPES=[{name:'Button Blaster',short:'BLASTER',role:'Splash damage',cost:100,range:170,damage:26,rate:1.15,color:'#ed9b5f',splash:65},{name:'Bunny Ranger',short:'RANGER',role:'Long range',cost:125,range:240,damage:32,rate:.85,color:'#8bc47b'},{name:'Frost Flipper',short:'FROST',role:'Chills enemies',cost:150,range:145,damage:8,rate:.75,color:'#95e1ef',slow:true},{name:'Stitch Engineer',short:'ENGINEER',role:'Rapid fire',cost:175,range:155,damage:11,rate:.19,color:'#ffd477'}];
export const PATH=[[72,254],[113,267],[159,274],[205,311],[256,350],[449,354],[485,344],[529,293],[572,244],[602,240],[724,241],[766,270],[822,337],[869,370],[1009,373],[1045,351],[1075,298],[1107,245],[1150,219],[1154,173]];
export const PADS=[[205,210],[355,270],[410,455],[555,380],[675,155],[715,365],[900,275],[950,465],[1165,335],[1130,435]];
export const LENGTHS=PATH.slice(1).map((p,i)=>Math.hypot(p[0]-PATH[i][0],p[1]-PATH[i][1]));export const TOTAL=LENGTHS.reduce((a,b)=>a+b,0);
export function position(distance){let d=distance;for(let i=0;i<LENGTHS.length;i++){if(d<=LENGTHS[i]){let t=Math.max(0,d/LENGTHS[i]);return{x:PATH[i][0]+(PATH[i+1][0]-PATH[i][0])*t,y:PATH[i][1]+(PATH[i+1][1]-PATH[i][1])*t};}d-=LENGTHS[i];}return{x:PATH.at(-1)[0],y:PATH.at(-1)[1]};}
export class Game{
constructor(){this.money=350;this.lives=20;this.wave=0;this.enemies=[];this.towers=[];this.shots=[];this.effects=[];this.queue=[];this.active=false;this.state='ready';this.kills=0;this.time=0;this.spawn=0;this.events=[];}
build(type,pad){const def=TYPES[type];if(!def||!PADS[pad]||this.towers.some(t=>t.pad===pad)||this.money<def.cost||['won','lost'].includes(this.state))return false;this.money-=def.cost;this.towers.push({type,pad,x:PADS[pad][0],y:PADS[pad][1],level:1,cooldown:0,spent:def.cost,recoil:0});return true;}
upgradeCost(t){return Math.round(TYPES[t.type].cost*(t.level===1?.75:1.2));}
upgrade(t){if(!this.towers.includes(t)||t.level>=3||this.money<this.upgradeCost(t))return false;let cost=this.upgradeCost(t);this.money-=cost;t.spent+=cost;t.level++;return true;}
sell(t){if(!this.towers.includes(t))return false;this.money+=Math.floor(t.spent*.7);this.towers.splice(this.towers.indexOf(t),1);return true;}
next(){if(this.active||this.wave>=15||['won','lost'].includes(this.state))return false;this.wave++;this.active=true;this.state='playing';this.spawn=.2;this.queue=Array.from({length:7+this.wave*2},(_,i)=>this.wave%5===0&&i===7?'brute':this.wave>=3&&i%4===2?'sock':'dust');return true;}
damage(e,n){if(e.hp<=0)return;e.hp-=n;e.flash=.1;if(e.hp<=0){this.money+=e.reward;this.kills++;this.events.push({type:'pop',x:e.x,y:e.y,value:e.reward});this.effects.push({x:e.x,y:e.y,life:.45,max:.45,color:'#ffe0a4',size:30,reward:e.reward});}}
update(dt){if(['won','lost'].includes(this.state))return;this.time+=dt;this.effects.forEach(e=>e.life-=dt);this.effects=this.effects.filter(e=>e.life>0);if(!this.active)return;this.spawn-=dt;if(this.queue.length&&this.spawn<=0){let kind=this.queue.shift(),brute=kind==='brute',sock=kind==='sock',hp=(brute?420:sock?62:45)*Math.pow(1.155,this.wave-1),p=position(0);this.enemies.push({...p,kind,hp,max:hp,d:0,speed:brute?30:sock?72:48,reward:brute?65:sock?13:10,slow:0,flash:0,seed:this.time});this.spawn=Math.max(.35,.95-this.wave*.025);}
for(const e of this.enemies){if(e.hp<=0)continue;e.slow=Math.max(0,e.slow-dt);e.flash=Math.max(0,e.flash-dt);e.d+=e.speed*(e.slow>0?.45:1)*dt;Object.assign(e,position(e.d));if(e.d>=TOTAL){e.hp=0;this.lives-=e.kind==='brute'?3:1;this.events.push({type:'leak'});}}
this.enemies=this.enemies.filter(e=>e.hp>0);if(this.lives<=0){this.lives=0;this.state='lost';this.active=false;return;}
for(const t of this.towers){t.cooldown-=dt;t.recoil=Math.max(0,t.recoil-dt*4);let def=TYPES[t.type],range=def.range+(t.level-1)*18,targets=this.enemies.filter(e=>Math.hypot(e.x-t.x,e.y-t.y)<range).sort((a,b)=>b.d-a.d);if(t.cooldown<=0&&targets.length){let e=targets[0];t.cooldown=def.rate/(1+(t.level-1)*.18);t.recoil=1;this.shots.push({x:t.x,y:t.y,startX:t.x,startY:t.y,target:e,speed:t.type===1?650:490,damage:def.damage*Math.pow(1.6,t.level-1),type:t.type,color:def.color});this.events.push({type:'shoot',tower:t.type});}}
for(const s of this.shots){let e=s.target,dx=e.x-s.x,dy=e.y-s.y,d=Math.hypot(dx,dy);if(d<s.speed*dt+8){s.hit=true;if(TYPES[s.type].splash){for(const a of this.enemies)if(Math.hypot(a.x-e.x,a.y-e.y)<TYPES[s.type].splash)this.damage(a,s.damage);this.effects.push({x:e.x,y:e.y,life:.3,max:.3,color:'#fbc974',size:65});}else if(e.hp>0){this.damage(e,s.damage);if(s.type===2){for(const a of this.enemies)if(Math.hypot(a.x-e.x,a.y-e.y)<65)a.slow=2;this.effects.push({x:e.x,y:e.y,life:.4,max:.4,color:'#a4efff',size:55});}}}else{s.x+=dx/d*s.speed*dt;s.y+=dy/d*s.speed*dt;}}
this.shots=this.shots.filter(s=>!s.hit);this.enemies=this.enemies.filter(e=>e.hp>0);if(!this.queue.length&&!this.enemies.length){this.active=false;this.shots=[];let bonus=55+this.wave*7;this.money+=bonus;this.events.push({type:'clear',value:bonus});this.state=this.wave===15?'won':'ready';}}
}
